package com.bananalab.lite;
import android.content.*;import org.json.*;import java.io.*;import java.util.*;import java.util.regex.*;
/** Bounded self-programming of a managed understanding class, gated by scene-effect comparisons. */
final class SelfLearning{
 static SharedPreferences prefs(Context c){return UnderstandingRuntime.prefs(c);}
 static JSONArray cases(Context c)throws Exception{return new JSONArray(prefs(c).getString("cases","[]"));}
 static int score(UnderstandingSpec spec,long seed,JSONArray user)throws Exception{return score(spec,CapabilityBench.fixtures(seed),user);}
 static int score(UnderstandingSpec spec,JSONArray rows,JSONArray user)throws Exception{int score=0;for(int i=0;i<12;i++){JSONObject row=rows.getJSONObject(i);SceneDraft scene=SceneDraft.read(row.getJSONObject("scene").toString());if(CapabilityBench.result(spec.rewrite(row.getString("input")),scene,row.getString("expected")))score++;}for(int i=0;i<user.length();i++){JSONObject row=user.getJSONObject(i);SceneDraft scene=SceneDraft.read(row.getJSONObject("scene").toString());CreatorSession.Result expected=CapabilityBench.apply(row.getString("canonical"),scene);if(CapabilityBench.result(spec.rewrite(row.getString("input")),scene,CapabilityBench.signature(expected.commit)))score++;}return score;}
 static UnderstandingSpec proposal(Context c)throws Exception{UnderstandingSpec old=UnderstandingRuntime.current(c);JSONArray users=cases(c),aliases=new JSONArray();Set<String> overridden=new HashSet<>();for(int i=0;i<users.length();i++)overridden.add(users.getJSONObject(i).getString("input"));for(int i=0;i<old.aliases.length();i++)if(!overridden.contains(old.aliases.getJSONObject(i).getString("input")))aliases.put(old.aliases.getJSONObject(i));for(int i=0;i<users.length();i++){JSONObject row=users.getJSONObject(i);aliases.put(new JSONObject().put("input",row.getString("input")).put("canonical",row.getString("canonical")));}JSONArray visible=CapabilityBench.fixtures(12345L);UnderstandingSpec selected=old;int best=score(old,visible,users);for(int mask=0;mask<8;mask++)if((mask&old.mask)==old.mask){UnderstandingSpec candidate=new UnderstandingSpec(mask,aliases);int n=score(candidate,visible,users);if(n>best){best=n;selected=candidate;}}return selected;}
 static String activate(Context c,UnderstandingSpec candidate,boolean requireGain)throws Exception{CapabilityBench.validateUser(cases(c));NaturalCoding.project(c);UnderstandingSpec before=UnderstandingRuntime.current(c);String old=prefs(c).getString("active",""),work=JavaProject.prefs(c).getString("working","{}"),base=JavaProject.fingerprint(c);Map<String,String> files=new LinkedHashMap<>();files.put("BananaBehavior.java",JavaPatchPolicy.BASE);files.put("UnderstandingCandidate.java",candidate.candidate("UnderstandingCandidate"));files.put("UnderstandingBaseline.java",before.candidate("UnderstandingBaseline"));JavaChat.phase("Compilando una mejora de comprensión en una copia…");OnDeviceJava.Build build=OnDeviceJava.compileSources(c,files);long seed=new java.security.SecureRandom().nextLong();JSONArray user=cases(c);JSONObject spec=new JSONObject().put("before",before.json()).put("after",candidate.json()).put("cases",user).put("seed",seed);JavaChat.phase("Comparando acciones, personajes y destinatarios en otro proceso…");android.os.Bundle proof=JavaTrial.request(c,build.jar,spec.toString(),"understanding",48+user.length());JSONObject report=new JSONObject(proof.getString("report"));boolean accepted=report.getInt("regressions")==0&&report.getInt("after")>=report.getInt("before")&&(!requireGain||report.getInt("after")>report.getInt("before"));report.put("accepted",accepted).put("requireGain",requireGain).put("base",base);prefs(c).edit().putString("report",report.toString()).commit();if(!accepted){LearningJournal.add(c,"rejected_candidate","Mejorar comprensión","Sin mejora comprobada o con regresiones: "+report.toString(),report.getInt("total"));return "Conservé la comprensión anterior: el candidato no mejoró las pruebas sin regresiones.\n"+report(c);}
 if(!old.equals(prefs(c).getString("active",""))||!work.equals(JavaProject.prefs(c).getString("working","{}"))||!base.equals(JavaProject.fingerprint(c)))throw new IOException("El proyecto cambió durante la evaluación.");String source=JavaProject.source(c,"UnderstandingRules.java");JSONObject row=new JSONObject().put("spec",candidate.json()).put("jar",build.jar.getAbsolutePath()).put("jarHash",ProjectRuntime.digest(build.jar)).put("sourceHash",JavaMethodEditor.hash(candidate.candidate("UnderstandingCandidate"))).put("report",report);java.lang.reflect.Method method=UnderstandingRuntime.method(c,row);JavaProject.stage(c,"UnderstandingRules.java",candidate.core());if(!prefs(c).edit().putString("backup",old).putString("backupSource",source).putString("base",base).putString("active",row.toString()).putString("coreHash",JavaMethodEditor.hash(candidate.core())).commit())throw new IOException("La copia quedó preparada; no pude publicar la mejora.");UnderstandingRuntime.active=method;LearningJournal.add(c,"verified_understanding","Mejorar comprensión","Antes "+report.getInt("before")+" → después "+report.getInt("after")+" de"+report.getInt("total")+" fixtures locales, sin regresiones. No mide inteligencia general.",report.getInt("total"));return "Programé, compilé y activé una mejora acotada de comprensión.\nArchivo: UnderstandingRules.java.\n"+report(c)+"\nYa se aplica a los próximos pedidos de escena. Para incorporarla al código de Banana.apk podés decir ‘incorporalo a la app’.";}
 static String report(Context c)throws Exception{String raw=prefs(c).getString("report","");if(raw.isEmpty())return "Todavía no hay una comparación ejecutada de comprensión. No inventé una puntuación de inteligencia.";JSONObject row=new JSONObject(raw);return "Evaluación local: "+row.getInt("before")+" → "+row.getInt("after")+" / "+row.getInt("total")+" casos. Regresiones: "+row.getInt("regressions")+".\nCandidato aceptado: "+row.getBoolean("accepted")+".\nComprueba efectos de escenas en copias con nombres y tipos variados. Son fixtures de desarrollo; no es un benchmark externo ni una medida de inteligencia general.";}
 static String correction(Context c,String input,String canonical)throws Exception{input=ChatLanguage.normalize(input);canonical=ChatLanguage.normalize(canonical);SceneDraft scene=MobileCore.scene(c);if(scene==null)scene=CapabilityBench.fixture(new Random(1));boolean named=false;for(SceneDraft.Actor actor:scene.cast)if(SceneDirector.word(input,actor.name)||!actor.label.isEmpty()&&SceneDirector.word(input,actor.label)||SceneDirector.word(input,actor.kind))named=true;if(!named)throw new IllegalArgumentException("El caso debe nombrar un personaje de la escena.");JSONArray users=cases(c),next=new JSONArray();for(int i=0;i<users.length();i++)if(!users.getJSONObject(i).getString("input").equals(input))next.put(users.getJSONObject(i));next.put(new JSONObject().put("input",input).put("canonical",canonical).put("scene",scene.json()).put("source","user_specification"));CapabilityBench.validateUser(next);if(!prefs(c).edit().putString("cases",next.toString()).commit())throw new IOException("No pude guardar el caso.");LearningJournal.add(c,"user_report",input,"Significado esperado aportado por vos: "+canonical+". Pendiente de evaluar una mejora.",0);return "Guardé tu significado esperado y una copia de la escena como caso de prueba. Todavía no cambié la comprensión. Podés pedirme ‘mejorá cómo entendés los pedidos’.";}
 static String undo(Context c)throws Exception{if(!prefs(c).contains("backup"))return "No hay una mejora anterior para recuperar.";NaturalCoding.project(c);if(!prefs(c).getString("base","").equals(JavaProject.fingerprint(c))||!JavaMethodEditor.hash(JavaProject.source(c,"UnderstandingRules.java")).equals(prefs(c).getString("coreHash","")))throw new IOException("La base o las fuentes cambiaron; revisalas antes de deshacer.");String backup=prefs(c).getString("backup","");java.lang.reflect.Method method=backup.isEmpty()?null:UnderstandingRuntime.method(c,new JSONObject(backup));JavaProject.stage(c,"UnderstandingRules.java",prefs(c).getString("backupSource",""));SharedPreferences.Editor edit=prefs(c).edit().remove("backup").remove("backupSource");if(backup.isEmpty())edit.remove("active");else edit.putString("active",backup);if(!edit.commit())throw new IOException("No pude recuperar la mejora anterior.");UnderstandingRuntime.active=method;return "Recuperé la comprensión anterior y su copia de fuentes. La APK instalada se conserva.";}
 static JSONObject portable(Context c)throws Exception{return new JSONObject().put("version",1).put("journal",LearningJournal.rows(c)).put("spec",UnderstandingRuntime.current(c).json()).put("cases",cases(c));}
 static void validate(JSONObject row)throws Exception{RuntimeProgram.keys(row,"version","journal","spec","cases");if(row.getInt("version")!=1)throw new IllegalArgumentException("Memoria incompatible.");LearningJournal.validate(row.getJSONArray("journal"));UnderstandingSpec.read(row.getJSONObject("spec"));CapabilityBench.validateUser(row.getJSONArray("cases"));}
 static void importPortable(Context c,JSONObject row)throws Exception{validate(row);if(!LearningJournal.prefs(c).contains("rows"))LearningJournal.prefs(c).edit().putString("rows",row.getJSONArray("journal").toString()).commit();if(!prefs(c).contains("cases"))prefs(c).edit().putString("cases",row.getJSONArray("cases").toString()).commit();if(!prefs(c).contains("active")){UnderstandingSpec spec=UnderstandingSpec.read(row.getJSONObject("spec"));if(!spec.json().toString().equals(UnderstandingSpec.read(new JSONObject(UnderstandingRules.spec())).json().toString()))activate(c,spec,false);}}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String q=NaturalCoding.normalize(input);Matcher correction=Pattern.compile("(?isu)^cuando pida ("+JavaTextPlan.LIT+") (?:entende|entiende|deberias entender|deberia entender) ("+JavaTextPlan.LIT+")$").matcher(NaturalCoding.polite(input));boolean improve=q.matches("(?:mejora|mejores) (?:tu comprension|como entendes los pedidos|como entendes pedidos con dos personajes|la comprension|como entendes las escenas)|hacete mas inteligente|mejora tu inteligencia"),report=q.matches("evalua tu inteligencia|evalua tu comprension|mostrame tu evaluacion|informe de mejoras|como mejoraste"),undo=q.matches("deshace la mejora de comprension|deshace tu ultima mejora"),status=q.matches("estado del aprendizaje propio|como podes mejorar sola");if(!improve&&!report&&!undo&&!status&&!correction.matches())return null;JavaChat.owner=Thread.currentThread();try{String text;if(correction.matches())text=correction(c,JavaTextPlan.decode(correction.group(1)),JavaTextPlan.decode(correction.group(2)));else if(improve)text=activate(c,proposal(c),true);else if(undo)text=undo(c);else if(report)text=report(c);else text="Aprendizaje propio comprobable\nComprensión instalada: "+UnderstandingRules.version()+".\nReglas activas: "+UnderstandingRuntime.current(c).mask+"; correcciones de escena: "+cases(c).length()+".\nPuedo reprogramar una clase preparada de comprensión, compilarla y comparar efectos en copias de escenas. No es autoentrenamiento ilimitado ni Java general.\nPodés pedir ‘mejorá cómo entendés los pedidos’, ‘mostrame tu evaluación’, ‘memoria de fallos’ o ‘entiende el proyecto’.";return MobileCore.say(c,text,"aprendizaje_local");}catch(Exception e){try{LearningJournal.add(c,"rejected_candidate",input,AndroidRepair.summary(e),0);}catch(Exception ignored){}return MobileCore.say(c,"No completé una mejora nueva: "+AndroidRepair.summary(e),"aprendizaje_local");}finally{JavaChat.owner=null;JavaChat.progress="";}}
}
